import React from 'react'

const Add = () => {
    return (
        <div className="form">
            <h1>Add New Member</h1>
            <input type="text" placeholder="name"></input>
            <input type="radio" placeholder="membershipYes">Membership</input>
            <input type="radio" placeholder="membershipNo"></input>
            <input type="text" placeholder="age"></input>
        </div>
    )
}

export default Add
